<Record name="Output2" type="delimited">
  <Field name="precinct" type="string" nullable="false" delimiter=";"/>
  <Field name="packets" type="integer" nullable="false" delimiter=";"/>
  <Field name="ballots" type="decimal" nullable="false" delimiter=";"/>
