Output port 0:
```xml
<Metadata id="output4">
<Record name="Output4" type="delimited">
  <Field name="borehole" type="string" nullable="false" delimiter=";"/>
  <Field name="earliest_core" type="date" nullable="false" delimiter=";"/>
  <Field name="accepted" type="long" nullable="false" delimiter=";"/>
